import java.util.Set;

public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId WARSAW = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE;
    private static final DateTimeFormatter INSTANT_FORMAT = DateTimeFormatter.ISO_OFFSET_DATE_TIME;
    private static final LocalTime CUTOFF = LocalTime.of(16, 0);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(1, 1), MonthDay.of(1, 6), MonthDay.of(5, 1),
            MonthDay.of(5, 3), MonthDay.of(8, 15), MonthDay.of(11, 1),
            MonthDay.of(11, 11), MonthDay.of(12, 25), MonthDay.of(12, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate ld = parseDate(date);
        return isBusinessDay(ld);
    }

    private boolean isBusinessDay(LocalDate ld) {
        return ld.getDayOfWeek() != DayOfWeek.SATURDAY && 
               ld.getDayOfWeek() != DayOfWeek.SUNDAY && 
               !HOLIDAYS.contains(MonthDay.from(ld));
    }

    private LocalDate parseDate(String date) {
        try {
            LocalDate ld = LocalDate.parse(date, DATE_FORMAT);
            if (!date.equals(ld.toString())) throw new IllegalArgumentException();
            return ld;
        } catch (DateTimeParseException | IllegalArgumentException e) {
            throw new IllegalArgumentException();
        }
    }

    private ZonedDateTime parseInstant(String instant) {
        try {
            return ZonedDateTime.parse(instant, INSTANT_FORMAT);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException();
        }
