            return date.format(DATE_FORMAT);
        }
        return nextBusinessDay(date).format(DATE_FORMAT);
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate proc = LocalDate.parse(processingDate(submittedAt), DATE_FORMAT);
        return nextBusinessDay(proc).format(DATE_FORMAT);
    }

    private LocalDate nextBusinessDay(LocalDate d) {
        LocalDate next = d.plusDays(1);
        while (!isBusinessDay(next)) next = next.plusDays(1);
        return next;
    }

